// Entradas do devlog, da mais antiga à mais recente (a versão sai da posição: 0.001.000, 0.001.001...). Acrescentar só no fim.
window.DEVLOG = [{"day": "2026-11-01","prompt": 559,"title": "Vila mais pequena e arrumada","desc": "A vila ficou mais compacta, com as mesmas casas e estruturas de antes mas melhor distribuídas. Antes, as casas grandes eram postas ao acaso e muitas ficavam de fora; agora cabem todas num espaço menor.","shot": null,"extra": []},{"day": "2026-11-01","prompt": 560,"title": "Só as moedas são atraídas","desc": "Apenas o ouro continua a voar para ti ao passares perto. Os restantes itens apanham-se com um clique quando estão ao alcance, ou com a tecla Z para apanhar tudo à volta. Assim já não recolhes por engano coisas que não querias.","shot": null,"extra": []},{"day": "2026-11-01","prompt": 561,"title": "Mais peso em cada golpe","desc": "Os golpes corpo a corpo ganharam impacto visível: o inimigo pisca em branco ao ser atingido, surge um clarão no ponto de contacto e o crítico tem um brilho dourado maior. A espada também demora mais nuns momentos do golpe do que noutros, e o inimigo encolhe e levanta pó ao ser empurrado.","shot": null,"extra": []},{"day": "2026-11-01","prompt": 566,"title": "Ataques inimigos avisam antes","desc": "Os inimigos passam a dar sinais claros de que vão atacar: recuam ligeiramente e a arma puxa para trás antes do golpe. Os mais lentos, como os chefes, avisam com mais antecedência, o que dá tempo para reagir.","shot": null,"extra": []},{"day": "2026-11-02","prompt": 571,"title": "Manequim de treino para testar dano","desc": "Podes agora construir um manequim de treino na bancada, com troncos e pedras, e colocá-lo onde quiseres. Mostra o dano de cada golpe e o maior golpe dado, o que ajuda a comparar armas. Mais tarde corrigimos o número para coincidir sempre com o golpe real.","shot": null,"extra": []},{"day": "2026-11-02","prompt": 572,"title": "Novo poder de arma: Phantom Strike","desc": "Há um novo poder para armas corpo a corpo. Pouco depois de cada golpe, um fantasma repete o ataque na mesma posição e direção, causando dano extra. As armas deixaram também de ter o rasto branco desenhado na própria imagem, e a lâmina vê-se agora no golpe.","shot": null,"extra": []},{"day": "2026-11-02","prompt": 573,"title": "Aviso vermelho com um ponto de exclamação","desc": "O aviso dos ataques inimigos passou de um flash branco a uma tinta vermelha sobre o inimigo, com um «!» por cima do nome. O branco fica reservado para quando o inimigo leva dano, e assim não se confundem.","shot": null,"extra": []},{"day": "2026-11-02","prompt": 575,"title": "Áreas de ataque marcadas no chão","desc": "As zonas perigosas, como a investida do javali ou os golpes dos chefes, deixam de ser manchas vermelhas chapadas. Passam a ver-se pegadas, pó e partículas no chão que vão aumentando até ao impacto, o que é mais bonito e continua fácil de ler.","shot": null,"extra": []},{"day": "2026-11-02","prompt": 578,"title": "Mais ecrã mostra mais mundo","desc": "Num ecrã com mais resolução vês agora mais mundo, em vez de tudo ficar maior. O interface e as personagens mantêm o tamanho, e a opção de escala de píxeis tem efeito real em cada valor, de 1x a 4x.","shot": null,"extra": []},{"day": "2026-11-02","prompt": 579,"title": "Dormir na cama a sério","desc": "Ao dormir, a tua personagem deita-se na cama com a mesma pose dos aldeões, e só meio segundo depois começa a passagem para o dia. Nesse instante podes cancelar com uma tecla.","shot": null,"extra": []},{"day": "2026-11-03","prompt": 589,"title": "Ataques na diagonal com corpo de três quartos","desc": "Os ataques na diagonal passaram a mostrar o corpo virado a três quartos, com a cara ou a nuca visíveis, em vez de reaproveitar poses de frente ou de costas. A arma é agora segurada sempre na mesma mão, e o rasto dos golpes ficou arredondado como o da espada.","shot": null,"extra": []},{"day": "2026-11-05","prompt": 591,"title": "Espadas com maior alcance","desc": "As cinco espadas ficaram com uma área de acerto 30% maior, o que torna os golpes mais generosos. Também os itens no chão ganharam sombra e, com o rato por cima, contorno e a mão como cursor, e o veado e o javali assentam melhor na sua sombra.","shot": null,"extra": []},{"day": "2026-11-06","prompt": 597,"title": "A água muda a forma de lutar","desc": "A água passou a ser uma barreira tática: orcs, bandidos e aranhas param na margem e dão a volta, enquanto esqueletos e múmias a atravessam pelo fundo. Estar molhado e usar armas pesadas dentro de água tem consequências, e os rios têm corrente.","shot": null,"extra": []},{"day": "2026-11-06","prompt": 598,"title": "Criaturas que vivem na água","desc": "Rios e lagos têm agora monstros próprios: crocodilos de emboscada, afogados à noite, bruxa do rio, sapos venenosos, sanguessugas, caranguejos gigantes, piranhas e um chefe, o Guardião do Lago. Cada um só nasce na água que lhe corresponde.","shot": null,"extra": []},{"day": "2026-11-06","prompt": 599,"title": "Um mundo com água e segredos","desc": "O mundo ganhou cascatas com grutas escondidas atrás, ilhas nos lagos grandes, ruínas afundadas com pontos de mergulho, oásis, pântanos venenosos e fontes termais. A chuva faz as águas cheias subir e podes cavar junto à água.","shot": null,"extra": []},{"day": "2026-11-06","prompt": 600,"title": "Pontes, jangadas e barcos","desc": "Podes agora atravessar e construir sobre a água: a ponte de madeira coloca-se e anda-se nela como em terra, e a jangada e o barco só navegam na água. A vila ganha um cais com pescador, um poço dos desejos, uma lavadeira e quatro missões ligadas à água.","shot": null,"extra": []},{"day": "2026-11-06","prompt": 601,"title": "Rachas nos blocos de terra mais bonitas","desc": "As rachas dos blocos de terreno são agora uma estrela com dentadas, em várias variantes, e só aparecem no lado que se vê. O bloco treme ao ser partido, com pó e migalhas, e mais tarde corrigimos as junções entre pedra e terra.","shot": null,"extra": []},{"day": "2026-11-07","prompt": 614,"title": "Cavalos mais rápidos e licença mais barata","desc": "O cavalo branco corre ao dobro do jogador e os outros sobem de forma gradual. A licença de equitação baixou de 3000 para 1000 moedas, o que a torna acessível mais cedo.","shot": null,"extra": []},{"day": "2026-11-07","prompt": 616,"title": "Feitiços de classe na mão esquerda","desc": "Chegaram as classes e os seus feitiços: a adaga do ninja traz quatro feitiços e o guerreiro ganha Investida, Ciclone, Terramoto e Berserk. Os feitiços sobem de nível com a Essência de Maré, que se obtém a pescar e se usa no Santuário das Marés. O escudo de madeira deixou de bloquear.","shot": null,"extra": []},{"day": "2026-11-07","prompt": 620,"title": "Pesca com níveis e cartas de melhoria","desc": "O minijogo da pesca ganhou progressão: ao subir de nível o jogo pára e escolhes uma de três cartas de melhoria, com raridades, troca e banimento. Também há poções melhores feitas com peixe, e as poções deixaram de ter tempo de espera.","shot": null,"extra": []},{"day": "2026-11-07","prompt": 621,"title": "Pesca com muito mais variedade","desc": "O minijogo da pesca ganhou mais de vinte melhorias novas, como a rede larga, o arpão e ajudantes, além de três evoluções. Os peixes passaram a ter comportamentos próprios (enguias, peixes tímidos, medusas, peixes-bomba e até tubarões) e surgem eventos durante a ronda. Cada partida fica assim mais imprevisível e com decisões a tomar.","shot": null,"extra": []},{"day": "2026-11-07","prompt": 622,"title": "Armas na mão certa ao andar","desc": "A arma e as ferramentas passaram a ser seguras na mão correta quando a personagem está virada para a direita, parada, a andar ou a correr. Mais tarde, as armas vistas de frente também passaram a ter a mão a agarrar o cabo, e o machado é espelhado quando se está virado para baixo. O resultado é um boneco que segura o equipamento de forma mais natural.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 624,"title": "A Árvore Anciã e os arbustos","desc": "O corte de madeira passou a fazer parte da natureza e os arbustos já se podem apanhar. Há uma Árvore Anciã com uma árvore de competências própria, com dezenas de habilidades a desbloquear. É mais uma forma de progredir ao explorar a floresta.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 626,"title": "Armas desenhadas por cima ou por baixo","desc": "A arma e a ferramenta passaram a ser desenhadas à frente ou atrás do corpo conforme a direção do movimento: à frente quando se vai para baixo ou para a direita, atrás para cima e para a esquerda. Também se espelham na vertical ao andar para a direita. O equipamento fica mais coerente em todas as direções.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 627,"title": "Ver o loot atrás dos blocos","desc": "Quando um item cai atrás de um bloco, passa a ver-se por cima dele com um pouco de transparência. Assim já não se perde o que fica escondido. Os itens no chão também ficaram mais pequenos, com exceção das moedas.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 629,"title": "Estilhaços de pedra mais realistas","desc": "Ao partir um bloco, os fragmentos são agora seixos redondos com sombra que rolam e ressaltam pelo chão. A picareta passou a poder partir blocos a qualquer ponto até três células de distância, sem se importar com o que está à frente. Partir pedra ficou mais satisfatório e menos fiscalizado.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 632,"title": "Combate mais fluido","desc": "Durante o ataque, a personagem pode agora mover-se devagar, a cerca de 10% da velocidade, em vez de ficar presa. O terramoto e o ciclone ganharam 30% mais alcance e o golpe fantasma é mais rápido. A investida do javali mostra um aviso antes de começar, e os inimigos mortos ficam um pouco mais tempo no chão.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 633,"title": "Noites mais escuras","desc": "À noite, só se vê claramente até uma certa distância à volta da personagem, com um degradé suave até ao escuro total. As fontes de luz abrem o seu próprio círculo de visão. A exploração noturna ganha mais tensão e atmosfera.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 634,"title": "Moedas guardadas nos baús","desc": "Os baús que aceitam moedas passaram a guardar um total à parte dos espaços de itens. Já se pode depositar e levantar dinheiro, que fica guardado com o mundo ou com a personagem. É uma forma segura de poupar.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 637,"title": "Mudar de área sem esperas","desc": "A área seguinte carrega em segundo plano quando o jogador se aproxima da fronteira. O ecrã de carregamento só aparece em mudanças mais longas. A viagem pelo mundo fica contínua e sem interrupções.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 641,"title": "Exame e licença de equitação","desc": "Há agora um exame de equitação em que o jogador chega a vários pontos a cavalo, com o Corcel de Prova emprestado. No fim, falar com o responsável do estábulo dá a licença e os parabéns. Aparece também uma dica para montar assim que se equipa uma montada.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 648,"title": "Novos atalhos de teclado","desc": "A montada passa a ser em Ctrl+H, a cura em H e as habilidades em Q, E, R e T. Os atalhos antigos foram reorganizados para evitar conflitos. A barra de feitiços foi também movida para a direita da barra rápida.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 649,"title": "Compêndio dentro do jogo","desc": "O glossário do jogo passou a estar no menu do Tab, com todas as entradas na língua escolhida. Os itens e outros elementos têm um atalho para abrir diretamente a sua página. O livro ganhou um ícone próprio, um livro azul com estrela prateada.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 654,"title": "Saber do Pescador","desc": "O pescador ensina melhorias permanentes para o minijogo da pesca, aprendidas num menu próprio e pagas com moedas e pérolas. O nível de pesca passou a decidir a qualidade dos peixes e os pontos a quantidade. A progressão é mais clara e recompensadora.","shot": null,"extra": []},{"day": "2026-11-08","prompt": 655,"title": "Nova linha de missões do Quest Giver","desc": "Foram acrescentadas oito missões entre os orcs e os ossos, que apresentam os contratos, as melhores ferramentas e a forja. A recompensa final passou a ser uma espada de pedra melhorada com o poder Slash Through, que deixa um rasto branco cortante no dash. A aldeia ganha uma história mais longa e com prémios mais interessantes.","shot": null,"extra": []},{"day": "2026-11-09","prompt": 659,"title": "Equipamento em forma de boneco","desc": "O ecrã do equipamento mostra agora a silhueta da personagem, com a armadura e a arma, e os espaços à volta ou ao lado. Foi pensado para se ver tudo sem tapar o boneco. É mais intuitivo perceber o que cada peça faz.","shot": null,"extra": []},{"day": "2026-11-09","prompt": 662,"title": "Ondas das pedras de portal","desc": "As pedras de portal soltam agora inimigos por vagas, sempre que perdem 20% de vida, em vez de a cada 20 segundos. O elite entra com a sua própria vaga, perto do fim. Ao partir a pedra, os inimigos que sobrarem morrem também, e deixam o loot habitual.","shot": null,"extra": []},{"day": "2026-11-09","prompt": 666,"title": "Estradas e caminhos no mundo","desc": "Os caminhos do mundo passaram a ser traçados como os rios: estradas de pedra que saem da vila e ligam as áreas entre si, com curvas naturais. Dão pistas de para onde ir e tornam o mundo mais vivo.","shot": null,"extra": []},{"day": "2026-11-09","prompt": 667,"title": "Contratos mais justos","desc": "Os contratos passaram a ter quantidades proporcionais ao tempo de recolha, e nunca pedem algo que se compre nas lojas para entregar com lucro. Também melhorou o menu do Treinador, com caixas separadas para o que cada poder pede e dá. Ficou mais claro o que fazer e o que se ganha.","shot": null,"extra": []},{"day": "2026-11-09","prompt": 671,"title": "Grutas com teto e morcegos","desc": "As grutas ganharam teto, que só se parte com a marreta, uma entrada na parede, o nome ao entrar, ambiente sonoro e morcegos. Os minérios ficaram com formas por metal, brilho e pó. Explorar o subsolo é agora mais atmosférico.","shot": null,"extra": []},{"day": "2026-11-09","prompt": 674,"title": "Mais FPS no mundo aberto","desc": "Foram aplicadas cinco correções ao desempenho: as áreas vizinhas fora do ecrã deixam de ser desenhadas e os dados de uso frequente ficam em memória. Também se pode escolher V-Sync e um limite de FPS nas definições de vídeo. Nota-se na fluidez, sobretudo em máquinas mais modestas.","shot": null,"extra": []},{"day": "2026-11-10","prompt": 687,"title": "Golpes de arma com mais peso","desc": "As espadas e os machados passam a começar devagar e a acabar depressa, o que dá mais peso a cada golpe. Os inimigos com armas parecidas ganham o mesmo ritmo. A velocidade de cada arma passou a ser medida em pontos: facas e lanças são rápidas, machados e espadas grandes são mais lentas.","shot": null,"extra": []},{"day": "2026-11-10","prompt": 689,"title": "Barras de vida mais nítidas","desc": "As barras de vida dos inimigos passaram a ser desenhadas por cima do mundo, com o nome, o nível e os números sempre legíveis e sem tremer quando a câmara se mexe. O nível fica agora à esquerda da barra, deixando de tapar as espadas e de colar à vida.","shot": "barras_nivel_720.png","extra": []},{"day": "2026-11-10","prompt": 696,"title": "Alcance do Cyclone em rajadas","desc": "O contorno do alcance do Cyclone é agora um anel de rajadas que giram à volta do jogador, no chão. O tamanho acompanha o alcance real: é menor de punhos nus do que com espada.","shot": null,"extra": []},{"day": "2026-11-10","prompt": 697,"title": "Animais como inimigos normais","desc": "Os animais da floresta deixam de ser um caso à parte e passam a ser inimigos como os outros, com nível, loot e experiência. Aparecem em mais sítios e o limite de inimigos vivos sobe para 25 de dia e 40 de noite. O veado também foge muito mais depressa.","shot": null,"extra": []},{"day": "2026-11-11","prompt": 701,"title": "Recall para a vila com efeitos","desc": "Voltar à vila ganhou um efeito a sério: o jogador carrega uma poça de luz com faíscas, desfaz-se em píxeis dos pés à cabeça numa coluna de luz e chega ao destino a reconstruir-se. Um clarão branco cobre a viagem entre os dois sítios.","shot": null,"extra": []},{"day": "2026-11-11","prompt": 703,"title": "Nova torre do mago","desc": "A torre do mago foi redesenhada à mão, mais detalhada, com telhado, hera e tijolos de pedra bem marcados. Usa só as cores da paleta do jogo, que passou a ser uma regra fixa para toda a arte.","shot": null,"extra": []},{"day": "2026-11-12","prompt": 707,"title": "Veado, javali, lobo e coelho novos","desc": "Os quatro animais da floresta ganharam animações novas de parado, corrida e morte, desenhadas com mais cuidado. As sombras foram acertadas aos novos corpos e os cascos pousam no chão como os pés do jogador.","shot": null,"extra": []},{"day": "2026-11-12","prompt": 711,"title": "Ferreiro e taberna renovados","desc": "Os edifícios do ferreiro e da taberna foram substituídos por desenhos novos, de pedra e madeira, com a forja acesa e fumo na chaminé da taberna. Mais tarde o estábulo da vila também ganhou um telhado de colmo com três boxes.","shot": "ferreiro_taberna_711.png","extra": []},{"day": "2026-11-12","prompt": 716,"title": "Corpo dentro de água","desc": "Quando entras na água, o corpo fica tingido com os tons da água e esbate-se até à linha de espuma, em vez de ser cortado. Há ondas, anéis e salpicos à tua volta, e uma opção nos vídeo permite desligar as ondas.","shot": "agua_corpo_716.gif","extra": []},{"day": "2026-11-13","prompt": 717,"title": "Entrada da dungeon em buraco","desc": "A entrada das dungeons passa a ser um buraco no chão com escadas a descer para norte, com uma versão para cada bioma. Entra-se pelo lado sul e as bordas bloqueiam o caminho.","shot": "buraco_dungeon.png","extra": []},{"day": "2026-11-13","prompt": 718,"title": "Cavaleiro novo no cavalo","desc": "O jogador a cavalo tem agora um corpo próprio, redesenhado, sentado na posição certa em cima do cavalo. A armadura aparece por peças (cabeça, tronco e pernas) tal como a vês a pé.","shot": "cavalo_novo_718.gif","extra": []},{"day": "2026-11-13","prompt": 719,"title": "Combate corpo a corpo renovado","desc": "Todas as armas de corte e de estocada partilham agora um só corpo de ataque, com investida e poeira, e um rasto de lâmina mais vivo. Os golpes passam a ser só nas quatro direções principais, o que os torna mais claros de ler.","shot": "ataques_corpo_unico_719.gif","extra": []},{"day": "2026-11-13","prompt": 721,"title": "Prata no lugar do chumbo","desc": "O chumbo foi substituído pela prata, e a escada de materiais fica pedra, ferro, prata, ouro e diamante. O ferro passa a ser o primeiro metal e mais escuro, e foram acrescentadas espadas e lanças de diamante, com o equilíbrio da floresta revisto.","shot": null,"extra": []},{"day": "2026-11-13","prompt": 722,"title": "Raios de sol mais bonitos","desc": "Os raios de sol deixam de ter princípio e fim marcados: desvanecem suavemente, têm uma poça de luz no chão, poeira a flutuar e uma respiração lenta. Aparecem em grupos pequenos e só em chão aberto.","shot": null,"extra": []},{"day": "2026-11-13","prompt": 724,"title": "Rondas de pesca à escolha","desc": "A ronda de pesca pode agora durar entre 10 segundos e 5 minutos, à escolha do jogador, e a Paciência permite subir esse tempo por níveis. As capturas custam cada vez mais e o quadro da vila ganhou tarefas de pesca.","shot": null,"extra": []},{"day": "2026-11-13","prompt": 725,"title": "Inimigos em grupos, sem comboios","desc": "Os inimigos aparecem agora em pequenos encontros, com espaço entre eles, em vez de se juntarem aos montes. Deixam também de te perseguir em comboio: perdem-te de vista ao fim de uns segundos, enquanto os pontos de interesse continuam mais cheios.","shot": null,"extra": []},{"day": "2026-11-13","prompt": 726,"title": "Pedras do portal com dez aspetos","desc": "As pedras do portal têm agora um aspeto diferente para cada um dos dez níveis, com brilho e luz próprios. Assim vês logo pelo desenho quão forte é o portal.","shot": null,"extra": []},{"day": "2026-11-13","prompt": 729,"title": "Corpos de inimigos com peso","desc": "Os inimigos caem com peso, deslizam um pouco no sentido do golpe e levantam pó ao tocar no chão. Deixam uma mancha própria de cada família e o corpo arrefece e desfaz-se aos poucos.","shot": null,"extra": []},{"day": "2026-11-13","prompt": 730,"title": "Grutas como cavidades naturais","desc": "As grutas foram refeitas como cavidades naturais dentro da rocha, sem boca nem teto artificiais. Algumas abrem numa fenda no chão e outras ficam seladas por blocos rachados, e o escuro liga-se ao fecho de cada uma.","shot": null,"extra": []},{"day": "2026-11-14","prompt": 740,"title": "Jogo mais leve e organizado","desc": "O código foi arrumado e medido com cuidado, o que torna o jogo mais fácil de evoluir. O envio de dados em jogo cooperativo é agora mais eficiente, mesmo com muitos inimigos, e nada pesa em repouso.","shot": null,"extra": []},{"day": "2026-11-14","prompt": 741,"title": "A arma varre à volta do boneco","desc": "No golpe corpo a corpo, o boneco fica parado e a arma varre à volta dele: a espada dá um quarto de volta e a lança vira e estoca. O rasto em arco acaba em degraus quentes e o machado de guerra ganhou um golpe esmagador próprio.","shot": "golpe_arma_volta_741.gif","extra": []},{"day": "2026-11-14","prompt": 745,"title": "O herói olha para o rato","desc": "O jogador passa a virar-se sempre para onde aponta o rato, parado, a andar ou a correr, e não apenas ao atacar. Em montaria, a pescar ou com menus abertos mantém a orientação normal. O golpe deixou de virar o herói sozinho, o que torna a mira mais previsível.","shot": null,"extra": []},{"day": "2026-11-14","prompt": 748,"title": "Golpes de lado mais naturais","desc": "Quando atacas de lado, a arma passa a vir de cima para baixo, como seria de esperar. Depois do golpe, o movimento regressa a velocidade total assim que o gesto acaba, sem tempo morto. As facas ganharam um golpe próprio de vai e vem, com dois cortes rápidos.","shot": "golpe_cima_baixo_748.gif","extra": ["faca_vai_e_vem_769.gif"]},{"day": "2026-11-14","prompt": 750,"title": "Nova pedra de waypoint","desc": "A pedra de teletransporte foi redesenhada com dois menires e um cristal a flutuar. Fica cinzenta e parada enquanto não a descobres, e passa a azul, a rodar, quando fica ativa.","shot": "waypoint_novo_750.gif","extra": []},{"day": "2026-11-14","prompt": 751,"title": "Taberna e ferreiro maiores","desc": "A taberna e o ferreiro foram redesenhados em tamanho idêntico ao das casas da vila, com mais detalhe. O ferreiro tem agora a chama da forja animada.","shot": "taberna_maior_751.png","extra": ["ferreiro_maior_752.gif"]},{"day": "2026-11-14","prompt": 757,"title": "Grutas com arte renovada","desc": "As grutas ganharam um chão escuro, estalagmites pequenas e paredes de rocha com fendas, tudo vindo do pack de arte do jogo. Mais tarde foi retirado o escurecimento por profundidade, ficando apenas a visão curta de noite. De dia a gruta tem o tom do céu e é mais fácil de ler.","shot": "gruta_dia_778.png","extra": ["gruta_noite_778.png"]},{"day": "2026-11-14","prompt": 759,"title": "Menos soluços e movimento mais suave","desc": "Libertar uma área do mundo e o resumo do ecrã de carregamento causavam pequenos picos de lentidão, e ficaram praticamente instantâneos. Com a interpolação da física, o movimento do herói, dos inimigos e dos aldeões fica fluido mesmo acima de 60 imagens por segundo.","shot": null,"extra": []},{"day": "2026-11-14","prompt": 763,"title": "Javali novo","desc": "O javali foi redesenhado com pernas mais curtas, ao tamanho do anterior e já com as cores do jogo. Nasce agora apenas entre os níveis 4 e 7.","shot": "javali_novo_763.gif","extra": []},{"day": "2026-11-14","prompt": 764,"title": "Menu inicial: a vila à noite","desc": "O fundo do menu inicial mostra agora a vila à noite com o aspeto real do jogo: taberna, ferreiro, casas, tochas, aldeões e luzes a tremeluzir. É a primeira coisa que vês e dá logo o tom do mundo.","shot": "menu_vila_noite_764.png","extra": []},{"day": "2026-11-14","prompt": 767,"title": "Equilíbrio de picaretas e armas de madeira","desc": "A picareta de madeira parte a terra em 2 golpes e a pedra em 4, e as outras picaretas foram ajustadas em conformidade. As armas de madeira passam a levar só troncos, sem pedra, o que facilita o início do jogo.","shot": null,"extra": []},{"day": "2026-11-14","prompt": 768,"title": "Slash Through só quando acerta","desc": "O rasto branco e o som do Slash Through só aparecem no dash se atingires inimigos. Sem acerto, é um dash normal, o que torna o efeito uma recompensa clara pelo bom timing.","shot": "slash_through_acerto_768.gif","extra": []},{"day": "2026-11-14","prompt": 770,"title": "Loot com ressaltos","desc": "Os itens largados são lançados mais longe, em arco, e ressaltam duas vezes antes de parar. Nunca passam para lá de um bloco. Os críticos que matam empurram também o corpo do inimigo três vezes mais longe, para um impacto mais forte.","shot": "loot_ressaltos_770.gif","extra": ["critico_empurra_779.gif"]},{"day": "2026-11-14","prompt": 771,"title": "Tocha nova","desc": "A tocha foi redesenhada com um fogo animado sobre um cabo mais pequeno. A luz e as brasas foram acertadas à nova chama.","shot": "tocha_v2_771.png","extra": []},{"day": "2026-11-14","prompt": 773,"title": "Crafting mais claro","desc": "O menu de crafting abre sempre com uma receita selecionada, e os itens escolhidos têm um contorno bem visível. Corrigimos o caso em que o contorno não aparecia num espaço desativado.","shot": "crafting_selecao_773.png","extra": []},{"day": "2026-11-14","prompt": 774,"title": "Ninja: bomba de fumo e clone","desc": "O ninja troca o shuriken e a armadilha por duas habilidades novas. A Bomba de Fumo cega os inimigos e permite ficar invisível, saindo com um crítico garantido. O Clone de Sombra é um aliado que copia o teu aspeto e luta a teu lado.","shot": "bomba_fumo_774.png","extra": ["clone_sombra_774.gif"]},{"day": "2026-11-14","prompt": 777,"title": "Casas de madeira e de pedra","desc": "O telhado verde-marinho das casas passa a cinzento de pedra, e cerca de metade das casas ficam de madeira e metade de pedra. Mais tarde as dezenas de casas geradas deram lugar a 15 casas desenhadas à mão, cujas janelas se acendem ao anoitecer.","shot": "casas_desenhadas_784.png","extra": ["as_15_casas_784.png","janelas_acesas_785.png"]},{"day": "2026-11-14","prompt": 780,"title": "O cavalo segue-te","desc": "O teu cavalo passa a acompanhar-te a uma certa distância, contornando obstáculos e evitando a água. Se ficar preso ou ficar muito para trás, salta para junto de ti. Funciona também em multijogador.","shot": "cavalo_segue_780.gif","extra": []},{"day": "2026-11-14","prompt": 782,"title": "Estrelas das missões por requisitos","desc": "As estrelas das missões ficam cinzentas enquanto não cumpres os níveis exigidos, e passam a amarelas (principais) ou azuis (secundárias) quando as podes aceitar. Percebes de relance o que já está ao teu alcance.","shot": "estrelas_requisitos_782.png","extra": []},{"day": "2026-11-15","prompt": 788,"title": "Brilho das peças pelo nível","desc": "Armas e armaduras brilham conforme o nível da peça, ao estilo dos clássicos de MMO: uma peça de nível 90 já começa a +6. Cada degrau acrescenta mais brilho e faíscas, visíveis ao andar e ao golpear.","shot": "brilho_nivel_788.gif","extra": ["brilho_andar_788.gif","brilho_golpe_788.gif"]},{"day": "2026-11-15","prompt": 789,"title": "A casa do jogador","desc": "Ganhas uma casa própria que evolui em três níveis, com melhoramentos no quadro de obras. Ao dormir na cama ficas Descansado e ganhas mais XP, e se morreres renasces à porta de casa. A Arca de Registo mostra o conteúdo de todos os baús.","shot": "casa_jogador_789.png","extra": ["quadro_melhoramentos_789.png","descanso_em_casa_790.png","renascer_porta_790.png","arca_registo_791.png"]},{"day": "2026-11-15","prompt": 792,"title": "Casa de nível 2: venda, contratos e pet","desc": "No nível 2 da casa podes vender itens ao preço das lojas sem sair de casa, e ganhas um contrato extra por dia, mais bem pago. Tens ainda um segundo animal de estimação a seguir-te, e os poderes dos dois somam-se.","shot": "caixa_venda_792.png","extra": ["contrato_extra_793.png","dois_pets_794.png"]},{"day": "2026-11-15","prompt": 795,"title": "Floresta e pântano fundidos","desc": "A floresta e a floresta escura são agora um só bioma, e o pântano surge conforme o nível da zona. Nos pântanos com nível mais alto aparecem lagos tóxicos, sanguessugas e inimigos mais perigosos.","shot": "floresta_3_linhas_795.png","extra": ["pantano_nivel3_795.png","pantano_nivel18_795.png","pantano_toxico_796.png"]},{"day": "2026-11-15","prompt": 798,"title": "Cura gradual","desc": "Os consumíveis passam a curar aos poucos, e a barra de vida mostra a parte que ainda vai ser recuperada. Quanto maior o nível, mais depressa a cura chega.","shot": "cura_gradual_798.png","extra": []},{"day": "2026-11-15","prompt": 799,"title": "Sacola e seis acessórios","desc": "A Sacola, feita com couro e corda, leva tudo o que apanhas diretamente para o inventário. O equipamento passa a ter seis espaços de acessórios, sem distinguir anéis de amuletos.","shot": "sacola_799.png","extra": ["equipamento_acessorios_800.png"]},{"day": "2026-11-15","prompt": 801,"title": "Plantas altas inteiras","desc": "As plantas altas, como os rabos-de-gato, as flores roxas e o feto, passam a aparecer inteiras e não cortadas a meio. Cada uma surge no sítio certo: junto à água, nos prados ou perto das árvores de outono.","shot": "plantas_altas_801.png","extra": ["plantas_altas_antes_801.png"]},{"day": "2026-11-15","prompt": 802,"title": "Cancelar e retomar missões","desc": "Podes cancelar missões secundárias e tarefas, com confirmação. As secundárias saem do diário e do ecrã, e retomam-se no NPC com o progresso intacto. A missão principal nunca se cancela. Ao entregar uma missão, a conversa continua logo com a seguinte do mesmo NPC.","shot": "cancelar_quest_802.png","extra": ["cancelar_confirmacao_802.png","retomar_quest_802.png","conversa_seguinte_805.png"]},{"day": "2026-11-15","prompt": 803,"title": "Altar dos poderes em grelha","desc": "O altar mostra os itens numa grelha com descrição ao passar o rato. Colocar um item é a primeira opção, e o separador ativo fica bem marcado. É mais rápido e claro de usar.","shot": "altar_grelha_803.png","extra": ["altar_retirar_803.png"]},{"day": "2026-11-15","prompt": 807,"title": "Picareta mais exigente e loot mais certeiro","desc": "A terra e a pedra precisam agora de pelo menos dois golpes da picareta, por mais forte que seja. A madeira das árvores e dos arbustos cai perto de onde foram cortados, em vez de voar para longe. A pá ganhou também as suas próprias animações na mão, e a tocha um ícone próprio.","shot": null,"extra": []},{"day": "2026-11-15","prompt": 809,"title": "Luzes à noite: forja, waypoint e taberna","desc": "A forja acende agora a luz cintilante da fornalha, tal como no menu inicial. Os waypoints descobertos ganham um halo azul fraco e a taberna passa a ter candeeiros acesos. À noite a vila fica mais viva e mais fácil de ler.","shot": "forja_luz_809.png","extra": ["forja_luz_antes_809.png","waypoint_noite_813.png","taberna_noite_813.png"]},{"day": "2026-11-15","prompt": 811,"title": "Inimigos distantes adormecem","desc": "Os inimigos que estão longe de todos os jogadores e sem nada a fazer ficam a dormir, e acordam quando alguém se aproxima ou os ataca. Também deixou de haver o soluço no jogo quando se chegava a acampamentos e cemitérios. Resultado: o jogo corre mais fluido em zonas cheias de monstros.","shot": null,"extra": []},{"day": "2026-11-15","prompt": 817,"title": "Casas de aldeões e de profissão","desc": "As casas onde os aldeões dormem passaram a ser diferentes das casas onde trabalham: nove casas distintas para dormir, e o padeiro, o herbanário e o mago têm cada um a sua. Há um herbanário novo e mais duas bancas na vila.","shot": "aldeia_de_cima_817.png","extra": ["padeiro_dentro_817.png","herbanario_dentro_817.png"]},{"day": "2026-11-15","prompt": 818,"title": "Cada feitiço com o seu tempo de lançamento","desc": "Os feitiços de classe têm agora um tempo de lançamento próprio: o efeito só sai no fim e a animação da arma ajusta-se a esse tempo. Dar um dash cancela o feitiço, mas sofrer dano não o interrompe.","shot": "cast_surprise_attack_greatsword_818.gif","extra": ["cast_poison_cloud_knife_818.gif","cast_earthquake_greatsword_818.gif","cast_dash_cancel_818.gif"]},{"day": "2026-11-15","prompt": 819,"title": "Estábulo isolado com terreiro de terra","desc": "O estábulo mudou para um canto afastado da vila, com um terreiro de terra à volta. Fica assim separado das casas e com um aspeto mais rural.","shot": "estabulo_isolado_819.png","extra": ["estabulo_dia_819.png"]},{"day": "2026-11-15","prompt": 820,"title": "Lama com chuva e poeira com sol","desc": "O chão de terra reage ao tempo: quando chove, os passos, os cascos e os dashes levantam lama, e quando está sol levantam poeira. Nota-se sobretudo no terreiro do estábulo e nas estradas.","shot": "terreiro_chuva_820.png","extra": ["terreiro_sol_820.png","passos_chuva_820.gif","cavalo_sol_820.gif"]},{"day": "2026-11-15","prompt": 821,"title": "Armas sem contorno colorido","desc": "As armas deixaram de ter um contorno colorido nos ícones e no chão. A cor do nível de melhoria passou para o nome do item, e essa cor depende agora do +n e do nível da peça, de cinzento até vermelho e preto nas armas mais fortes.","shot": "sem_contorno_inventario_821.png","extra": ["sem_contorno_inventario_antes_821.png","sem_contorno_chao_antes_821.png","sem_contorno_chao_821.png"]},{"day": "2026-11-15","prompt": 823,"title": "Candeeiros de rua na vila","desc": "A vila ganhou candeeiros medievais de poste com lanterna, espalhados pela praça, pelas ruas e pelos caminhos das oficinas. Acendem à noite e dão à aldeia um ar acolhedor. Também as janelas das casas dos aldeões iluminam agora o exterior depois de escurecer.","shot": null,"extra": []},{"day": "2026-11-15","prompt": 824,"title": "Interiores no próprio mundo","desc": "As casas deixaram de ter um ecrã de interior à parte: a sala fica por baixo da casa, no próprio mundo, e a fachada desvanece quando se entra. As divisões têm mobília por conjuntos (quarto, cozinha, trabalho, arrumos), a forja, a taberna e a torre do mago em vários pisos também. À noite há velas e lume na sala onde o jogador está.","shot": "luz_sala_827.png","extra": []},{"day": "2026-11-15","prompt": 831,"title": "Cavalo mais bem comportado","desc": "O cavalo segue o jogador sem oscilar de lado e à sua velocidade, e deixa de seguir quando o jogador se afasta muito. Com Ctrl+B pode mandar-se embora, e o cavalo já não entra atrás do jogador em casas e masmorras.","shot": null,"extra": []},{"day": "2026-11-16","prompt": 832,"title": "Placa da zona em duas linhas","desc": "O nome da zona no minimapa já não sai do ecrã quando é comprido: aparece em duas linhas, com o bioma e a posição, centrado debaixo do anel.","shot": "placa_zona_815.png","extra": ["placa_zona_antes_815.png"]},{"day": "2026-11-16","prompt": 838,"title": "Três campas novas","desc": "Há três novas campas (musgosa, com cruz e com caveira) que se obtêm como variante da campa normal. Servem para as mesmas receitas, só mudam o aspeto.","shot": null,"extra": []},{"day": "2026-11-17","prompt": 840,"title": "Jogo mais rápido","desc": "Mediu-se onde o jogo gastava mais tempo e otimizou-se: metade dos tiles deixou de ser desenhada e o ritmo subiu 20 a 30 por cento. Todos os cenários testados passam agora dos 90 fps de média, e a vila anda entre 160 e 180.","shot": null,"extra": []},{"day": "2026-11-17","prompt": 842,"title": "Novos ecrãs de arranque e logo","desc": "O arranque mostra o banner do jogo com um fade para o menu, e o menu tem o novo logo do título com a espada. Enquanto o mundo é gerado, um pequeno diorama monta-se por camadas e acompanha o progresso.","shot": "arranque_banner_859.png","extra": ["loading_arranque_842.gif","geracao_diorama_859.png","menu_logo_843.png"]},{"day": "2026-11-17","prompt": 844,"title": "Vila mais bonita e acolhedora","desc": "A vila foi redesenhada: casas em bandas viradas a sul, ruas direitas dentro de uma muralha retangular com três portas, e uma praça com uma árvore grande ao centro. Há ainda um lago com doca para pescar, sebes, flores e bandeirolas.","shot": "vila_bandas_844.png","extra": ["praca_nova_844.png","great_tree_vila_858.png"]},{"day": "2026-11-17","prompt": 845,"title": "Quatro poderes de arma novos","desc": "Quatro poderes para armas corpo a corpo, com partículas: Ciclone, Onda de Foice, Estilhaço e Gémeo de Lâmina. Aplicam-se no altar e podem sair dos baús das masmorras.","shot": "poder_ciclone_845.gif","extra": ["poder_onda_foice_845.gif","poder_estilhaco_845.gif","poder_gemeo_lamina_845.gif"]},{"day": "2026-11-17","prompt": 846,"title": "Muralha de troncos para construir","desc": "Há sete peças novas de muralha de troncos para colocar: blocos, cantos e lados. Só os 16 pixéis de baixo bloqueiam a passagem, e as peças fecham um retângulo sem falhas.","shot": "muralha_troncos_846.png","extra": []},{"day": "2026-11-17","prompt": 847,"title": "Cinco pets novos","desc": "Chegam a Toupeira Mineira, o Cogumelo Colhedor, a Pega Ladra, o Pato de Borracha e o Gato da Vila. A toupeira ajuda a picar blocos, o cogumelo colhe plantas, a pega traz o loot dos abates, e o pato e o gato têm as suas pequenas recompensas.","shot": "pets_cinco_847.gif","extra": ["pet_pega_847.gif","pet_toupeira_847.gif","pet_cogumelo_847.gif"]},{"day": "2026-11-17","prompt": 848,"title": "Brilho metálico nas armas melhoradas","desc": "O brilho das armas melhoradas ganhou saturação e contraste, com um efeito metálico e um raio de luz que passa de tempos a tempos. Já não muda a cor da arma para a do nível, e sincroniza-se na mão, nos ícones e no chão.","shot": "brilho_metalico_848.gif","extra": []},{"day": "2026-11-17","prompt": 849,"title": "Rasto ao andar: poeira, relva e pedra","desc": "O jogador deixa agora um rasto que depende do chão: poeira e torrões na terra seca, só lama clara quando molhado, lâminas de relva cortada e lascas na pedra. Os outros jogadores deixam o mesmo rasto.","shot": "rasto_terra_849.gif","extra": ["rasto_relva_849.gif","rasto_pedra_849.gif","rasto_chuva_849.gif"]},{"day": "2026-11-17","prompt": 850,"title": "Interiores mais vivos e arrumados","desc": "As salas ficaram mais cuidadas: mobília encostada à parede, postes com tocha, sombras e luz das janelas. Há zonas (lume, cama com arca, mesa no tapete), tralha de quem lá mora, e vida como vapor, pó na luz e o morador ao lume.","shot": null,"extra": []},{"day": "2026-11-17","prompt": 853,"title": "Água realista em cavalo e jogador","desc": "A água reage ao corpo que a atravessa: linha de água ondulada, espuma e anéis que nascem do movimento. O mesmo modelo serve para o jogador a pé, o cavalo, os outros jogadores, inimigos e animais, e os anéis esvanecem em vez de desaparecerem de repente.","shot": "agua_cavalo_853.gif","extra": ["agua_jogador_854.gif"]},{"day": "2026-11-19","prompt": 855,"title": "Interiores dentro do contorno da casa","desc": "O interior de cada casa respeita agora o contorno do seu exterior e usa os mesmos materiais (madeira, estuque ou pedra). As portas encaixam no chão sem emenda.","shot": "interiores_contorno_855.png","extra": ["interiores_material_856.png","interiores_porta_857.png"]},{"day": "2026-11-19","prompt": 858,"title": "Novas Grande Árvore e Árvore Antiga","desc": "A Grande Árvore e a Árvore Antiga foram substituídas por desenhos novos. A Árvore Antiga tem os cristais a brilhar com luz fria e a colisão cobre o tronco e o altar.","shot": "great_tree_mundo_858.png","extra": ["ancient_tree_858.png"]},{"day": "2026-11-19","prompt": 865,"title": "Descansar na taberna como na cama","desc": "Ao descansar na taberna, o ecrã escurece como na cama e o dia salta para a manhã às escuras. A mensagem de que dormiste bem só aparece quando já é de dia.","shot": "taberna_escuro_865.png","extra": ["taberna_mensagem_865.png"]},{"day": "2026-11-19","prompt": 869,"title": "Rasto de passos diferente em cada chão","desc": "Os passos do jogador deixam agora marcas próprias na terra, na relva e na pedra, ao ritmo de cada pé que pousa. A terra levanta baforadas e grãos, a relva solta lâminas e pétalas e a pedra mostra um pequeno anel e seixos. O resultado é um chão que reage a quem o pisa.","shot": "rasto_terra_869.gif","extra": ["rasto_relva_869.gif","rasto_pedra_869.gif"]},{"day": "2026-11-19","prompt": 870,"title": "Feitiços de classe para as três classes","desc": "Cada classe ganha quatro feitiços próprios e um item de classe. O tanque tem gancho de corrente, desafio, muralha e rocha viva, o arqueiro prende e chove flechas, e o mago teletransporta-se, cria singularidades, levita e prende inimigos. Dão a cada classe um papel claro em combate.","shot": "feiticos_tank_870.png","extra": ["feiticos_archer_871.png","feiticos_mage_872.png","feiticos_icones_872.png"]},{"day": "2026-11-20","prompt": 873,"title": "Janela de opções com tamanho fixo","desc": "A janela das opções deixa de mudar de tamanho de separador para separador. Tem cabeçalho, corpo com deslize e rodapé com o botão de voltar, e encolhe para nunca encostar às bordas do ecrã.","shot": "opcoes_modal_873.png","extra": []},{"day": "2026-11-20","prompt": 874,"title": "Árvores da vila que se podem cortar","desc": "As árvores da praça e dos relvados da vila podem agora ser abatidas. Caem os troncos, fica um toco e, passado algum tempo, a árvore volta a crescer.","shot": "arvores_vila_874.png","extra": []},{"day": "2026-11-20","prompt": 875,"title": "Sementes e árvores plantadas por ti","desc": "Cada árvore abatida deixa uma semente que podes plantar fora da vila, em terreno onde as árvores crescem. A árvore passa por várias fases até estar adulta, o que permite repor a floresta ou criar a tua.","shot": "sementes_plantar_875.png","extra": ["sementes_fases_875.png"]},{"day": "2026-11-22","prompt": 876,"title": "Um estilo visual unificado","desc": "Foi definido um guia de estilo para a interface e a arte, com cores e medidas nomeadas e uma cena de catálogo para ver tudo junto. O jogo ficou mais coerente e passou a verificar sozinho que as regras de contorno e cores são respeitadas.","shot": "design_catalogo_876.png","extra": ["design_inventario_876.png"]},{"day": "2026-11-22","prompt": 877,"title": "Seis criaturas redesenhadas com contorno","desc": "O sapo, o caranguejo, o crocodilo, o troll da gruta, o guardião do lago e a tocha de estimação ganharam um contorno escuro à volta. Deixam de destoar das restantes criaturas e leem-se melhor no cenário.","shot": "contorno_ai_877.png","extra": []},{"day": "2026-11-22","prompt": 878,"title": "Casas feitas de blocos","desc": "As casas passam a ser montadas peça a peça, com paredes, chãos, telhados e portas de vários materiais. Há mais de cem peças novas, incluindo mobília e portas abertas, o que permite casas muito mais variadas e detalhadas.","shot": "blocos_catalogo_878.png","extra": ["blocos_pecas_878.png","blocos_taberna_879.png","blocos_camadas_879.png"]},{"day": "2026-11-22","prompt": 880,"title": "Entrar e subir nas casas","desc": "Podes entrar nas casas, abrir portas ao chegar e subir escadas até aos pisos de cima. Ao entrar, o telhado e os pisos superiores esvanecem-se para veres o interior, com uma transição suave.","shot": "blocos_entrar_880.gif","extra": ["pisos_cima_881.png"]},{"day": "2026-11-22","prompt": 881,"title": "A vila inteira feita de blocos","desc": "Todos os edifícios da vila passam a ser casas de blocos com interior completo. Os aldeões sobem as escadas até à cama e, à noite, as janelas da frente acendem-se.","shot": "vila_blocos_881.png","extra": ["vila_blocos_noite_881.png","taberna_dentro_881.png"]},{"day": "2026-11-22","prompt": 882,"title": "Construir e partir blocos","desc": "O jogador pode agora construir as suas próprias casas com dezenas de tipos de blocos, escadas, janelas, chaminés e decorações, piso a piso. Também se podem partir blocos, e as alterações ficam guardadas.","shot": "blocos_construir_882.gif","extra": ["blocos_po_893.gif"]},{"day": "2026-11-23","prompt": 884,"title": "Pesca: o minijogo abre na boia","desc": "Ao cair, a boia abre logo a janela da pesca, que cresce a partir dela com a câmara a aproximar-se. A ronda só começa quando mordes o primeiro peixe, o que torna o arranque mais natural.","shot": "pesca_abertura_884.gif","extra": []},{"day": "2026-11-23","prompt": 885,"title": "Escadas sem sair da casa","desc": "Corrigido o problema em que, ao descer as escadas de uma casa, aparecia o exterior como se tivesses saído. A vista mantém-se coerente nas escadas, nos dois sentidos.","shot": "escadas_vista_885.gif","extra": []},{"day": "2026-11-23","prompt": 886,"title": "Pesca renovada: o lago visto de cima","desc": "O minijogo de pesca foi refeito com o lago visto de cima, peixes a chegar de qualquer lado e em qualquer ângulo, e arte em dezasseis direções. Há nove estilos de nado, e a boia fica na água durante a ronda toda, com um golpe certeiro quando o peixe morde.","shot": "pesca_angulos_886.gif","extra": ["pesca_strike_887.gif"]},{"day": "2026-11-23","prompt": 888,"title": "Cartas de pesca e maré viva","desc": "O baralho da pesca ficou só com ferramentas, com menos cartas e mais claras, e há cardumes e peixes-bomba. Quando o baralho acaba, chega uma maré viva.","shot": "pesca_mare_viva_888.gif","extra": ["pesca_gestos_889.gif"]},{"day": "2026-11-23","prompt": 891,"title": "Graus do pescador e níveis de pesca","desc": "A pesca dá experiência por captura e tem agora cinco graus, cada um a limitar o nível até cumprires requisitos noutras competências. Um cadeado no separador das competências mostra o que falta.","shot": "graus_pescador_891.png","extra": ["cadeado_pesca_891.png"]},{"day": "2026-11-23","prompt": 892,"title": "Águas frescas e águas cansadas","desc": "Cada água esgota-se se pescares demasiado e recupera ao longo do dia. Numa água cansada ganhas metade da experiência e não aparecem achados nem chefes, com avisos claros na janela da pesca.","shot": "aguas_cansadas_892.png","extra": ["pesca_ronda_892.gif"]},{"day": "2026-11-24","prompt": 894,"title": "Comando com mira e botões para tudo","desc": "Com um comando, mira-se com o manípulo direito e os feitiços, a montada e as outras ações têm botões próprios através de um modificador. Também os menus se podem usar com o comando e os glifos mostram as teclas certas.","shot": "mira_comando_894.gif","extra": ["glifos_feiticos_894.png"]},{"day": "2026-11-24","prompt": 895,"title": "Interface com acabamento em madeira","desc": "As barras de deslize passam a ser de madeira, o aviso dos itens fica melhor posicionado, a área da missão foi organizada e há confirmação ao voltar ao menu principal, que grava antes de sair.","shot": "scrollbar_madeira_895.png","extra": ["area_missao_895.png","menu_principal_895.png"]},{"day": "2026-11-24","prompt": 896,"title": "Descrições em mais de cem itens","desc": "Mais de cem itens que não tinham descrição passam a explicar para que servem, o que ajuda a perceber o que cada coisa faz.","shot": "descricoes_896.png","extra": []},{"day": "2026-11-24","prompt": 902,"title": "Vender peças com poderes","desc": "Quando vendes uma peça com poderes colocados, eles ficam guardados e voltam contigo se a recomprares.","shot": "revenda_poderes_902.png","extra": []},{"day": "2026-11-24","prompt": 903,"title": "Raridade dos itens","desc": "Os itens têm agora raridade, de comum a super raro, visível nas descrições, na loja e no compêndio. Os animais de estimação são os mais raros.","shot": "raridade_903.png","extra": []},{"day": "2026-11-24","prompt": 905,"title": "Contratos gerados todos os dias","desc": "O quadro de contratos gera tarefas novas por dia, ajustadas ao nível do jogador, com recompensas calculadas conforme o tempo e o perigo. Há também tarefas raras e extra.","shot": "quadro_gerado_905.png","extra": ["quadro_rara_905.png"]},{"day": "2026-11-24","prompt": 906,"title": "Névoa de guerra com ar de fumo","desc": "A névoa que esconde o mapa tem agora o aspeto de fumo animado, com orla ondulante, tanto de dia como de noite. Ficou mais bonita e mais leve para o aparelho.","shot": "fog_fumo_906.gif","extra": ["fog_fumo_noite_906.gif"]},{"day": "2026-11-24","prompt": 909,"title": "Anilhas da água só na água","desc": "As ondas na água esbatem-se até desaparecer na margem e deixam de aparecer por cima de monstros e animais, o que dá um efeito mais natural.","shot": "anilhas_margem_909.gif","extra": ["anilhas_corpos_909.gif"]},{"day": "2026-11-24","prompt": 911,"title": "Andar enquanto se ataca","desc": "Ao mover-te durante um golpe, as pernas do personagem andam em vez de ficarem paradas, e ouvem-se passos e marcam-se pegadas. Os outros jogadores veem o mesmo, e também o rasto do dash de espada.","shot": "golpe_a_andar_911.gif","extra": ["rasto_rede_899.gif"]},{"day": "2026-11-24","prompt": 913,"title": "Pegadas que ficam no chão","desc": "As pegadas foram refeitas: covas na terra, erva pisada e solas na pedra, com terra a cair das botas. Passaram a pesar muito menos no desempenho.","shot": "rasto_terra_913.gif","extra": ["rasto_relva_913.gif"]},{"day": "2026-11-24","prompt": 914,"title": "Contratos de itens de missão","desc": "Há um novo tipo de contrato em que tens de obter um item de missão de um monstro ou chefe, como relíquias de família e roupas roubadas. São vinte itens novos, com arte própria.","shot": "itens_missao_914.png","extra": ["itens_missao_queda_914.png"]},{"day": "2026-11-24","prompt": 915,"title": "Portas que cabem na parede","desc": "As portas ficam mais baixas e deixam de passar por cima da viga que separa os pisos. Casas como a caiada ficaram mais bem proporcionadas.","shot": "portas_viga_915.png","extra": ["porta_caiada_915.png"]},{"day": "2026-11-24","prompt": 918,"title": "Chain Hook com mais alcance","desc": "O gancho de corrente do tanque ganha o triplo do alcance. A descrição dos feitiços passa a mostrar sempre o ícone, com largura limitada.","shot": "tooltip_feiticos_918.png","extra": []},{"day": "2026-11-24","prompt": 921,"title": "Mobília da vila que se parte","desc": "A mobília das casas dos aldeões pode agora ser partida e deixa um item a quem a parte. Foi também ajustada a colisão exterior das casas para seguir o contorno do rés do chão.","shot": "mobilia_aldeia_921.gif","extra": ["colisao_forja_919.png","colisao_norte_919.png"]}];
